WITH enriched AS (SELECT id, customer_id, account_type, balance, opened_date, status, CUME_DIST() OVER (PARTITION BY status ORDER BY balance NULLS LAST) balance_cume_dist, AVG(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) balance_avg_6, SUM(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_balance FROM accounts) SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, CASE WHEN balance >= 89000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, account_type, COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) AS closed_count, APPROX_PERCENTILE(balance_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS balance_cume_dist_quartiles, SORT_ARRAY(COLLECT_SET(account_type)) AS account_type_list, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM enriched GROUP BY CUBE (DATE_TRUNC('QUARTER', opened_date), CASE WHEN balance >= 89000 THEN 'HIGH' ELSE 'LOW' END, account_type) HAVING COUNT(DISTINCT customer_id) > 1;
